if (!items.length || !items[0].json.id) return [{ json: { no_candidate: true } }];
const c = items[0].json;
if ((Number(c.cannibalization_risk) || 0) > 0.65) return [{ json: { no_candidate: true, reason: 'cannibalization_risk_above_threshold', candidate_id: c.id } }];
return items;

const get = (n) => { try { return $(n).all(); } catch (e) { return null; } };
const gate = get('Publication Gate');
let summary;
if (gate) { const ready = gate.filter(i => i.json.ready).length; summary = { drafts_created: gate.length, ready, blocked: gate.length - ready }; }
else { summary = { drafts_created: 0, no_candidate: true }; }
return [{ json: { summary, tasks_created: 0 } }];
